import { PASSWORD, USERS, expect, test } from "../fixtures";

test.describe("sign out", () => {
  test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
    // Arrange: sign in so the session cookie is stored in the request context's cookie jar.
    const login = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: PASSWORD },
    });
    expect(login.status()).toBe(200);
    const sessionBefore = (await request.storageState()).cookies.find((c) => c.name === "session");
    expect(sessionBefore?.value).toBeTruthy();

    // Act
    const response = await request.post("/api/auth/logout");

    // Assert: status
    expect(response.status()).toBe(204);

    // Assert: the session cookie is cleared (expired or zeroed by Set-Cookie)
    const setCookie = response
      .headersArray()
      .filter((h) => h.name.toLowerCase() === "set-cookie")
      .map((h) => h.value)
      .find((v) => v.startsWith("session="));
    expect(setCookie).toBeDefined();
    const lower = setCookie!.toLowerCase();
    const expiredByMaxAge = lower.includes("max-age=0");
    const expiredByDate = lower.includes("expires=") && lower.includes("1970");
    expect(expiredByMaxAge || expiredByDate).toBe(true);

    // Assert: the cookie jar no longer holds a usable session value
    const sessionAfter = (await request.storageState()).cookies.find((c) => c.name === "session");
    expect(sessionAfter?.value ?? "").toBe("");
  });
});
